/* YouTube 底部栏精简：只保留 首页/订阅/我，删掉 Shorts 和 + 号按钮 */
(function(){
  let body;
  try { body = JSON.parse($response.body); } catch(e){ $done({}); return; }
  const HIDE = ["FEshorts", "FEuploads"];
  let changed = false;
  function walk(o){
    if (Array.isArray(o)){
      for (let i = o.length - 1; i >= 0; i--){
        const it = o[i];
        const bid = it && (it.iconRender?.browseId ?? it.labelRender?.browseId);
        if (bid && HIDE.includes(bid)){ o.splice(i,1); changed = true; continue; }
        if (it && typeof it === "object") walk(it);
      }
    } else if (o && typeof o === "object"){
      for (const k in o) walk(o[k]);
    }
  }
  walk(body);
  $done(changed ? {body: JSON.stringify(body)} : {});
})();
